CREATE OR REPLACE FUNCTION public.accessible_subjects() RETURNS text[] LANGUAGE sql STABLE SET search_path=public AS $$ SELECT CASE WHEN public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.subscriptions s WHERE s.user_id=auth.uid() AND s.is_trial AND NOT s.revoked AND s.starts_at<=now() AND s.ends_at>now()) THEN (SELECT coalesce(array_agg(DISTINCT subject),'{}') FROM public.decks) ELSE (SELECT coalesce(array_agg(DISTINCT ps.subject),'{}') FROM public.subscriptions s JOIN public.plan_subjects ps ON ps.plan_id=s.plan_id WHERE s.user_id=auth.uid() AND NOT s.revoked AND s.starts_at<=now() AND s.ends_at>now()) END $$;
CREATE OR REPLACE FUNCTION public.has_subject_access(_subject text) RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT _subject=ANY(public.accessible_subjects()) $$;
CREATE OR REPLACE FUNCTION elixir_private.admin_allocate_trial(_user uuid,_plan text,_days integer,_start date,_note text DEFAULT '',_subscription uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; IF _days IS NULL OR _days<1 OR _days>3650 OR _start IS NULL OR _note IS NULL OR length(_note)>480 THEN RAISE EXCEPTION 'Choose 1–3650 trial days, a start date and a valid note'; END IF; IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=_user) OR NOT EXISTS(SELECT 1 FROM public.subscription_plans WHERE id=_plan) THEN RAISE EXCEPTION 'Student or plan not found'; END IF; IF _subscription IS NULL THEN INSERT INTO public.subscriptions(user_id,plan_id,starts_at,ends_at,approved_by,amount_paid_paise,allocation_note,is_trial) VALUES(_user,_plan,_start::timestamptz,_start::timestamptz+make_interval(days=>_days),auth.uid(),0,'Trial · '||_note,true) RETURNING id INTO sid; ELSE UPDATE public.subscriptions SET starts_at=_start::timestamptz,ends_at=_start::timestamptz+make_interval(days=>_days),amount_paid_paise=0,allocation_note='Trial · '||_note,is_trial=true WHERE id=_subscription AND user_id=_user AND plan_id=_plan AND payment_request_id IS NULL AND is_trial RETURNING id INTO sid; IF NOT FOUND THEN RAISE EXCEPTION 'Trial not found'; END IF; END IF; UPDATE public.trial_requests SET status='approved',days=_days,subscription_id=sid,reviewed_by=auth.uid() WHERE user_id=_user AND (status='pending' OR subscription_id=sid); INSERT INTO public.admin_audit(actor_id,action,entity,record_key,changed_fields) VALUES(auth.uid(),CASE WHEN _subscription IS NULL THEN 'allocate_trial' ELSE 'edit_trial' END,'subscriptions',sid::text,'["starts_at","ends_at","is_trial"]'); RETURN sid; END $$;